@@ -0,0 +1,312 @@
+/**
+ * Auth Controller Tests
+ * 
+ * Tests the HTTP controller layer including:
+ * - Sign up endpoint
+ * - Sign in endpoint
+ * - Input validation
+ * - Error responses
+ * - Success responses
+ */
+
+import { describe, it, expect, beforeEach, vi } from "vitest";
+import { AuthController } from "./auth.controller";
+import { SignUpUseCase } from "../../use-cases/sign-up.use-case";
+import { SignInUseCase } from "../../use-cases/sign-in.use-case";
+import { InMemoryUserRepository } from "../repositories/in-memory-user-repository";
+import { MockPasswordHasher, MockPasswordVerifier } from "../password-adapters";
+import type { FastifyRequest, FastifyReply } from "fastify";
+
+describe("AuthController", () => {
+  let controller: AuthController;
+  let mockRequest: Partial<FastifyRequest>;
+  let mockReply: Partial<FastifyReply>;
+
+  beforeEach(() => {
+    const repository = new InMemoryUserRepository();
+    const hasher = new MockPasswordHasher();
+    const verifier = new MockPasswordVerifier();
+    const sessionFactory = {
+      create: async (userId: string) => `session_${userId}`,
+    };
+
+    const signUpUseCase = new SignUpUseCase(repository, hasher);
+    const signInUseCase = new SignInUseCase(repository, verifier, sessionFactory);
+
+    controller = new AuthController(signUpUseCase, signInUseCase);
+
+    // Create mock request/reply
+    mockRequest = {
+      body: {},
+    };
+
+    mockReply = {
+      status: vi.fn().mockReturnThis(),
+      send: vi.fn(),
+    };
+  });
+
+  describe("signUp()", () => {
+    it("should return 201 on successful registration", async () => {
+      mockRequest.body = {
+        email: "john@example.com",
+        password: "SecurePassword123",
+        name: "John Doe",
+      };
+
+      await controller.signUp(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      expect(mockReply.status).toHaveBeenCalledWith(201);
+      expect(mockReply.send).toHaveBeenCalled();
+
+      const response = (mockReply.send as any).mock.calls[0][0];
+      expect(response.ok).toBe(true);
+      expect(response.data.userId).toBeDefined();
+      expect(response.data.email).toBe("john@example.com");
+    });
+
+    it("should return 400 if email is invalid", async () => {
+      mockRequest.body = {
+        email: "invalid-email",
+        password: "SecurePassword123",
+        name: "John Doe",
+      };
+
+      await controller.signUp(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      expect(mockReply.status).toHaveBeenCalledWith(400);
+      const response = (mockReply.send as any).mock.calls[0][0];
+      expect(response.ok).toBe(false);
+    });
+
+    it("should return 400 if password is too short", async () => {
+      mockRequest.body = {
+        email: "john@example.com",
+        password: "short",
+        name: "John Doe",
+      };
+
+      await controller.signUp(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      expect(mockReply.status).toHaveBeenCalledWith(400);
+      const response = (mockReply.send as any).mock.calls[0][0];
+      expect(response.message).toContain("Validation failed");
+    });
+
+    it("should return 400 if name is empty", async () => {
+      mockRequest.body = {
+        email: "john@example.com",
+        password: "SecurePassword123",
+        name: "",
+      };
+
+      await controller.signUp(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      expect(mockReply.status).toHaveBeenCalledWith(400);
+      const response = (mockReply.send as any).mock.calls[0][0];
+      expect(response.message).toContain("Validation failed");
+    });
+
+    it("should return 400 if email already exists", async () => {
+      mockRequest.body = {
+        email: "john@example.com",
+        password: "SecurePassword123",
+        name: "John Doe",
+      };
+
+      // First registration
+      await controller.signUp(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      // Reset mocks
+      mockReply.status = vi.fn().mockReturnThis();
+      mockReply.send = vi.fn();
+
+      // Second registration with same email
+      await controller.signUp(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      expect(mockReply.status).toHaveBeenCalledWith(400);
+      const response = (mockReply.send as any).mock.calls[0][0];
+      expect(response.error).toContain("Email already registered");
+    });
+
+    it("should include message in response", async () => {
+      mockRequest.body = {
+        email: "john@example.com",
+        password: "SecurePassword123",
+        name: "John Doe",
+      };
+
+      await controller.signUp(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      const response = (mockReply.send as any).mock.calls[0][0];
+      expect(response.message).toBeDefined();
+    });
+  });
+
+  describe("signIn()", () => {
+    beforeEach(async () => {
+      // Create a test user first
+      mockRequest.body = {
+        email: "john@example.com",
+        password: "SecurePassword123",
+        name: "John Doe",
+      };
+
+      mockReply.status = vi.fn().mockReturnThis();
+      mockReply.send = vi.fn();
+
+      const repository = new InMemoryUserRepository();
+      const hasher = new MockPasswordHasher();
+      const verifier = new MockPasswordVerifier();
+      const sessionFactory = {
+        create: async (userId: string) => `session_${userId}`,
+      };
+
+      const signUpUseCase = new SignUpUseCase(repository, hasher);
+      const signInUseCase = new SignInUseCase(repository, verifier, sessionFactory);
+
+      controller = new AuthController(signUpUseCase, signInUseCase);
+
+      await controller.signUp(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+    });
+
+    it("should return 200 on successful sign in", async () => {
+      mockReply.status = vi.fn().mockReturnThis();
+      mockReply.send = vi.fn();
+
+      mockRequest.body = {
+        email: "john@example.com",
+        password: "SecurePassword123",
+      };
+
+      await controller.signIn(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      expect(mockReply.status).toHaveBeenCalledWith(200);
+      const response = (mockReply.send as any).mock.calls[0][0];
+      expect(response.ok).toBe(true);
+      expect(response.data.sessionToken).toBeDefined();
+    });
+
+    it("should return 401 with invalid password", async () => {
+      mockReply.status = vi.fn().mockReturnThis();
+      mockReply.send = vi.fn();
+
+      mockRequest.body = {
+        email: "john@example.com",
+        password: "WrongPassword123",
+      };
+
+      await controller.signIn(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      expect(mockReply.status).toHaveBeenCalledWith(401);
+      const response = (mockReply.send as any).mock.calls[0][0];
+      expect(response.ok).toBe(false);
+    });
+
+    it("should return 401 with nonexistent email", async () => {
+      mockReply.status = vi.fn().mockReturnThis();
+      mockReply.send = vi.fn();
+
+      mockRequest.body = {
+        email: "nonexistent@example.com",
+        password: "SecurePassword123",
+      };
+
+      await controller.signIn(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      expect(mockReply.status).toHaveBeenCalledWith(401);
+    });
+
+    it("should return 400 if email is invalid", async () => {
+      mockReply.status = vi.fn().mockReturnThis();
+      mockReply.send = vi.fn();
+
+      mockRequest.body = {
+        email: "invalid-email",
+        password: "SecurePassword123",
+      };
+
+      await controller.signIn(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      expect(mockReply.status).toHaveBeenCalledWith(400);
+      const response = (mockReply.send as any).mock.calls[0][0];
+      expect(response.message).toContain("Validation failed");
+    });
+
+    it("should return session token in response", async () => {
+      mockReply.status = vi.fn().mockReturnThis();
+      mockReply.send = vi.fn();
+
+      mockRequest.body = {
+        email: "john@example.com",
+        password: "SecurePassword123",
+      };
+
+      await controller.signIn(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      const response = (mockReply.send as any).mock.calls[0][0];
+      expect(response.data.sessionToken).toBeTruthy();
+      expect(typeof response.data.sessionToken).toBe("string");
+    });
+  });
+
+  describe("error handling", () => {
+    it("should handle unexpected errors in signUp", async () => {
+      mockRequest.body = {
+        email: "john@example.com",
+        password: "SecurePassword123",
+        name: "John Doe",
+      };
+
+      // Simulate invalid body type
+      mockRequest.body = null;
+
+      await controller.signUp(
+        mockRequest as FastifyRequest,
+        mockReply as FastifyReply
+      );
+
+      expect(mockReply.status).toHaveBeenCalled();
+      expect(mockReply.send).toHaveBeenCalled();
+    });
+  });
+});

