@@ -0,0 +1,178 @@
+/**
+ * Password Adapters Tests
+ * 
+ * Tests the mock and null password adapters:
+ * - MockPasswordHasher/Verifier (for testing)
+ * - NullPasswordHasher/Verifier (for testing without real hashing)
+ */
+
+import { describe, it, expect } from "vitest";
+import {
+  MockPasswordHasher,
+  MockPasswordVerifier,
+  NullPasswordHasher,
+  NullPasswordVerifier,
+} from "./password-adapters";
+
+describe("Password Adapters", () => {
+  describe("MockPasswordHasher", () => {
+    const hasher = new MockPasswordHasher();
+
+    it("should hash a password", async () => {
+      const plaintext = "mypassword";
+      const hash = await hasher.hash(plaintext);
+
+      expect(hash).toBeDefined();
+      expect(typeof hash).toBe("string");
+    });
+
+    it("should create bcrypt-like hash format", async () => {
+      const plaintext = "mypassword";
+      const hash = await hasher.hash(plaintext);
+
+      // Should match bcrypt format: $2b$10$ + 22 salt + 31 hash
+      expect(hash).toMatch(/^\$2b\$10\$/);
+    });
+
+    it("should produce 60-character bcrypt-format hash", async () => {
+      const plaintext = "mypassword";
+      const hash = await hasher.hash(plaintext);
+
+      // Bcrypt hashes are exactly 60 characters
+      expect(hash).toHaveLength(60);
+    });
+
+    it("should encode password length in hash", async () => {
+      const plaintext = "mypassword";
+      const hash = await hasher.hash(plaintext);
+
+      // Hash should include encoded length
+      expect(hash).toBeDefined();
+      expect(typeof hash).toBe("string");
+    });
+
+    it("should produce consistent hashes", async () => {
+      const plaintext = "mypassword";
+      const hash1 = await hasher.hash(plaintext);
+      const hash2 = await hasher.hash(plaintext);
+
+      expect(hash1).toBe(hash2);
+    });
+
+    it("should produce different hashes for different passwords", async () => {
+      const hash1 = await hasher.hash("password1");
+      const hash2 = await hasher.hash("password2");
+
+      expect(hash1).not.toBe(hash2);
+    });
+  });
+
+  describe("MockPasswordVerifier", () => {
+    const hasher = new MockPasswordHasher();
+    const verifier = new MockPasswordVerifier();
+
+    it("should verify correct password", async () => {
+      const plaintext = "mypassword";
+      const hash = await hasher.hash(plaintext);
+
+      const isValid = await verifier.verify(plaintext, hash);
+
+      expect(isValid).toBe(true);
+    });
+
+    it("should reject wrong password", async () => {
+      const plaintext = "mypassword";
+      const hash = await hasher.hash(plaintext);
+
+      const isValid = await verifier.verify("wrongpassword", hash);
+
+      expect(isValid).toBe(false);
+    });
+
+    it("should be sensitive to password length", async () => {
+      const hash = await hasher.hash("short");
+
+      const isValid = await verifier.verify("shorterpassword", hash);
+
+      expect(isValid).toBe(false);
+    });
+
+    it("should work with the hasher", async () => {
+      const password = "TestPassword123";
+      const hash = await hasher.hash(password);
+      const isValid = await verifier.verify(password, hash);
+
+      expect(isValid).toBe(true);
+    });
+  });
+
+  describe("NullPasswordHasher", () => {
+    const hasher = new NullPasswordHasher();
+
+    it("should return plaintext as hash (for testing)", async () => {
+      const plaintext = "mypassword";
+      const hash = await hasher.hash(plaintext);
+
+      expect(hash).toBe(plaintext);
+    });
+
+    it("should preserve original password", async () => {
+      const password = "ComplexPassword!@#123";
+      const hash = await hasher.hash(password);
+
+      expect(hash).toBe(password);
+    });
+  });
+
+  describe("NullPasswordVerifier", () => {
+    const hasher = new NullPasswordHasher();
+    const verifier = new NullPasswordVerifier();
+
+    it("should verify by string comparison (for testing)", async () => {
+      const plaintext = "mypassword";
+      const hash = await hasher.hash(plaintext);
+
+      const isValid = await verifier.verify(plaintext, hash);
+
+      expect(isValid).toBe(true);
+    });
+
+    it("should reject different passwords", async () => {
+      const hash = "storedpassword";
+      const isValid = await verifier.verify("differentpassword", hash);
+
+      expect(isValid).toBe(false);
+    });
+
+    it("should be case-sensitive", async () => {
+      const hash = "mypassword";
+      const isValid = await verifier.verify("MyPassword", hash);
+
+      expect(isValid).toBe(false);
+    });
+  });
+
+  describe("Integration", () => {
+    it("MockPasswordHasher should work with MockPasswordVerifier", async () => {
+      const hasher = new MockPasswordHasher();
+      const verifier = new MockPasswordVerifier();
+
+      const password = "TestPassword123";
+      const hash = await hasher.hash(password);
+      const isValid = await verifier.verify(password, hash);
+
+      expect(isValid).toBe(true);
+    });
+
+    it("NullPasswordHasher should work with NullPasswordVerifier", async () => {
+      const hasher = new NullPasswordHasher();
+      const verifier = new NullPasswordVerifier();
+
+      const password = "TestPassword123";
+      const hash = await hasher.hash(password);
+      const isValid = await verifier.verify(password, hash);
+
+      expect(isValid).toBe(true);
+    });
+  });
+});

