+/**
+ * InMemory User Repository Tests
+ * 
+ * Tests the in-memory repository adapter including:
+ * - CRUD operations
+ * - Email index
+ * - Error handling
+ * - Test helpers
+ */
+
+import { describe, it, expect, beforeEach } from "vitest";
+import { InMemoryUserRepository } from "./in-memory-user-repository";
+import { User } from "../../domain/entities/user";
+import { Email } from "../../domain/value-objects/email";
+import { Password } from "../../domain/value-objects/password";
+
+describe("InMemoryUserRepository", () => {
+  let repository: InMemoryUserRepository;
+  // Valid bcrypt hash (60 chars: $2b$10$ + 22 salt + 31 hash)
+  const validPasswordHash = "$2b$10$REDACTED";
+
+  beforeEach(() => {
+    repository = new InMemoryUserRepository();
+  });
+
+  describe("save()", () => {
+    it("should save a user", async () => {
+      const user = User.create(
+        "user_1",
+        "john@example.com",
+        "John Doe",
+        validPasswordHash
+      );
+
+      const saved = await repository.save(user);
+
+      expect(saved).toEqual(user);
+    });
+
+    it("should throw error if email already exists", async () => {
+      const user1 = User.create(
+        "user_1",
+        "john@example.com",
+        "John Doe",
+        validPasswordHash
+      );
+
+      const user2 = User.create(
+        "user_2",
+        "john@example.com",
+        "Jane Doe",
+        validPasswordHash
+      );
+
+      await repository.save(user1);
+
+      await expect(() => repository.save(user2)).rejects.toThrow(
+        "Email already exists"
+      );
+    });
+
+    it("should be retrievable after save", async () => {
+      const user = User.create(
+        "user_1",
+        "john@example.com",
+        "John Doe",
+        validPasswordHash
+      );
+
+      await repository.save(user);
+      const retrieved = await repository.findById(user.id);
+
+      expect(retrieved).toBeDefined();
+      expect(retrieved?.id).toBe(user.id);
+    });
+  });
+
+  describe("findById()", () => {
+    it("should find a user by ID", async () => {
+      const user = User.create(
+        "user_1",
+        "john@example.com",
+        "John Doe",
+        validPasswordHash
+      );
+
+      await repository.save(user);
+      const found = await repository.findById(user.id);
+
+      expect(found).toBeDefined();
+      expect(found?.id).toBe(user.id);
+      expect(found?.email.value).toBe("john@example.com");
+    });
+
+    it("should return null if user not found", async () => {
+      const found = await repository.findById("nonexistent_id");
+      expect(found).toBeNull();
+    });
+  });
+
+  describe("findByEmail()", () => {
+    it("should find a user by email", async () => {
+      const user = User.create(
+        "user_1",
+        "john@example.com",
+        "John Doe",
+        validPasswordHash
+      );
+
+      await repository.save(user);
+      const found = await repository.findByEmail("john@example.com");
+
+      expect(found).toBeDefined();
+      expect(found?.email.value).toBe("john@example.com");
+    });
+
+    it("should find user by email case-insensitively", async () => {
+      const user = User.create(
+        "user_1",
+        "john@example.com",
+        "John Doe",
+        validPasswordHash
+      );
+
+      await repository.save(user);
+      const found = await repository.findByEmail("JOHN@EXAMPLE.COM");
+
+      expect(found).toBeDefined();
+      expect(found?.email.value).toBe("john@example.com");
+    });
+
+    it("should return null if email not found", async () => {
+      const found = await repository.findByEmail("nonexistent@example.com");
+      expect(found).toBeNull();
+    });
+  });
+
+  describe("emailExists()", () => {
+    it("should return true if email exists", async () => {
+      const user = User.create(
+        "user_1",
+        "john@example.com",
+        "John Doe",
+        validPasswordHash
+      );
+
+      await repository.save(user);
+      const exists = await repository.emailExists("john@example.com");
+
+      expect(exists).toBe(true);
+    });
+
+    it("should return true for email with different case", async () => {
+      const user = User.create(
+        "user_1",
+        "john@example.com",
+        "John Doe",
+        validPasswordHash
+      );
+
+      await repository.save(user);
+      const exists = await repository.emailExists("JOHN@EXAMPLE.COM");
+
+      expect(exists).toBe(true);
+    });
+
+    it("should return false if email does not exist", async () => {
+      const exists = await repository.emailExists("nonexistent@example.com");
+      expect(exists).toBe(false);
+    });
+  });
+
+  describe("update()", () => {
+    it("should update an existing user", async () => {
+      const user = User.create(
+        "user_1",
+        "john@example.com",
+        "John Doe",
+        validPasswordHash
+      );
+
+      await repository.save(user);
+
+      // Create updated user
+      const updatedUser = new User(
+        user.id,
+        user.email,
+        "Jane Doe", // changed name
+        user.passwordHash,
+        user.createdAt,
+        new Date(),
+        user.isActive,
+        user.emailVerified
+      );
+
+      const result = await repository.update(updatedUser);
+
