+/**
+ * User Entity Tests
+ * 
+ * Tests the User aggregate including:
+ * - Factory methods (create, fromDatabase)
+ * - Business rules (canAuthenticate, isFullyVerified)
+ * - Data serialization (toPlainObject)
+ * - Value object encapsulation (Email, Password)
+ */
+
+import { describe, it, expect, beforeEach } from "vitest";
+import { User } from "./user";
+import { Email } from "../value-objects/email";
+import { Password } from "../value-objects/password";
+
+describe("User Entity", () => {
+  let validEmail: Email;
+  let validPassword: Password;
+  const validUserId = "user_12345";
+  const validName = "John Doe";
+  // Valid bcrypt hash (60 chars: $2b$10$ + 22 salt + 31 hash)
+  const validPasswordHash = "$2b$10$REDACTED";
+
+  beforeEach(() => {
+    validEmail = new Email("john@example.com");
+    validPassword = new Password(validPasswordHash);
+  });
+
+  describe("constructor", () => {
+    it("should create a user with all properties", () => {
+      const now = new Date();
+      const user = new User(
+        validUserId,
+        validEmail,
+        validName,
+        validPassword,
+        now,
+        now,
+        true,
+        false
+      );
+
+      expect(user.id).toBe(validUserId);
+      expect(user.email).toBe(validEmail);
+      expect(user.name).toBe(validName);
+      expect(user.passwordHash).toBe(validPassword);
+      expect(user.createdAt).toBe(now);
+      expect(user.updatedAt).toBe(now);
+      expect(user.isActive).toBe(true);
+      expect(user.emailVerified).toBe(false);
+    });
+
+    it("should have default values for isActive (true) and emailVerified (false)", () => {
+      const now = new Date();
+      const user = new User(
+        validUserId,
+        validEmail,
+        validName,
+        validPassword,
+        now,
+        now
+      );
+
+      expect(user.isActive).toBe(true);
+      expect(user.emailVerified).toBe(false);
+    });
+  });
+
+  describe("canAuthenticate()", () => {
+    it("should return true when user is active", () => {
+      const user = User.create(
+        validUserId,
+        validEmail.value,
+        validName,
+        validPassword.hash
+      );
+
+      expect(user.canAuthenticate()).toBe(true);
+    });
+
+    it("should return false when user is inactive", () => {
+      const now = new Date();
+      const user = new User(
+        validUserId,
+        validEmail,
+        validName,
+        validPassword,
+        now,
+        now,
+        false, // isActive = false
+        false
+      );
+
+      expect(user.canAuthenticate()).toBe(false);
+    });
+  });
+
+  describe("isFullyVerified()", () => {
+    it("should return true when user is active and email verified", () => {
+      const now = new Date();
+      const user = new User(
+        validUserId,
+        validEmail,
+        validName,
+        validPassword,
+        now,
+        now,
+        true, // isActive = true
+        true  // emailVerified = true
+      );
+
+      expect(user.isFullyVerified()).toBe(true);
+    });
+
+    it("should return false when user is inactive but email verified", () => {
+      const now = new Date();
+      const user = new User(
+        validUserId,
+        validEmail,
+        validName,
+        validPassword,
+        now,
+        now,
+        false, // isActive = false
+        true   // emailVerified = true
+      );
+
+      expect(user.isFullyVerified()).toBe(false);
+    });
+
+    it("should return false when user is active but email not verified", () => {
+      const now = new Date();
+      const user = new User(
+        validUserId,
+        validEmail,
+        validName,
+        validPassword,
+        now,
+        now,
+        true,  // isActive = true
+        false  // emailVerified = false
+      );
+
+      expect(user.isFullyVerified()).toBe(false);
+    });
+
+    it("should return false when user is inactive and email not verified", () => {
+      const now = new Date();
+      const user = new User(
+        validUserId,
+        validEmail,
+        validName,
+        validPassword,
+        now,
+        now,
+        false, // isActive = false
+        false  // emailVerified = false
+      );
+
+      expect(user.isFullyVerified()).toBe(false);
+    });
+  });
+
+  describe("create() factory method", () => {
+    it("should create a new user with default values", () => {
+      const user = User.create(
+        validUserId,
+        validEmail.value,
+        validName,
+        validPassword.hash
+      );
+
+      expect(user.id).toBe(validUserId);
+      expect(user.email.value).toBe(validEmail.value);
+      expect(user.name).toBe(validName);
+      expect(user.passwordHash.hash).toBe(validPassword.hash);
+      expect(user.isActive).toBe(true);
+      expect(user.emailVerified).toBe(false);
+    });
+
+    it("should create email value object from string", () => {
+      const user = User.create(
+        validUserId,
+        "test@example.com",
+        validName,
+        validPassword.hash
+      );
+
+      expect(user.email).toBeInstanceOf(Email);
+      expect(user.email.value).toBe("test@example.com");
+    });
+
+    it("should create password value object from hash", () => {
+      const user = User.create(
+        validUserId,
+        validEmail.value,
+        validName,
+        validPassword.hash
+      );
+
+      expect(user.passwordHash).toBeInstanceOf(Password);
+      expect(user.passwordHash.hash).toBe(validPassword.hash);
+    });
+
+    it("should set createdAt and updatedAt to current time", () => {
+      const beforeCreate = new Date();
+      const user = User.create(
+        validUserId,
+        validEmail.value,
+        validName,
+        validPassword.hash
+      );
+      const afterCreate = new Date();
+
+      expect(user.createdAt.getTime()).toBeGreaterThanOrEqual(beforeCreate.getTime());
+      expect(user.createdAt.getTime()).toBeLessThanOrEqual(afterCreate.getTime());
+      expect(user.updatedAt.getTime()).toBeGreaterThanOrEqual(beforeCreate.getTime());
+      expect(user.updatedAt.getTime()).toBeLessThanOrEqual(afterCreate.getTime());
+    });
+
+    it("should throw if email is invalid", () => {
+      expect(() => {
+        User.create(
+          validUserId,
+          "invalid-email",
+          validName,
+          validPassword.hash
+        );
+      }).toThrow("Invalid email format");
+    });
+
+    it("should throw if password hash is invalid", () => {
+      expect(() => {
+        User.create(
+          validUserId,
+          validEmail.value,
+          validName,
+          "not-a-bcrypt-hash"
+        );
+      }).toThrow("Password must be a valid bcrypt hash");
+    });
+  });
+
+  describe("fromDatabase() factory method", () => {
+    it("should reconstruct user from database data", () => {
+      const createdAt = new Date("2024-01-01T00:00:00Z");
+      const updatedAt = new Date("2024-01-02T00:00:00Z");
+
+      const user = User.fromDatabase({
+        id: validUserId,
+        email: validEmail.value,
+        name: validName,
+        passwordHash: validPassword.hash,
+        createdAt,
+        updatedAt,
+        isActive: true,
+        emailVerified: true,
+      });
+
+      expect(user.id).toBe(validUserId);
+      expect(user.email.value).toBe(validEmail.value);
+      expect(user.name).toBe(validName);
+      expect(user.passwordHash.hash).toBe(validPassword.hash);
+      expect(user.createdAt).toBe(createdAt);
+      expect(user.updatedAt).toBe(updatedAt);
+      expect(user.isActive).toBe(true);
+      expect(user.emailVerified).toBe(true);
+    });
+
+    it("should preserve timestamps from database", () => {
+      const createdAt = new Date("2023-06-15T10:30:00Z");
+      const updatedAt = new Date("2024-01-20T15:45:30Z");
+
+      const user = User.fromDatabase({
+        id: validUserId,
+        email: validEmail.value,
+        name: validName,
+        passwordHash: validPassword.hash,
+        createdAt,
+        updatedAt,
+        isActive: true,
+        emailVerified: false,
+      });
+
+      expect(user.createdAt).toEqual(createdAt);
+      expect(user.updatedAt).toEqual(updatedAt);
+    });
+
+    it("should throw if email in data is invalid", () => {
+      expect(() => {
+        User.fromDatabase({
+          id: validUserId,
+          email: "invalid-email",
+          name: validName,
+          passwordHash: validPassword.hash,
+          createdAt: new Date(),
+          updatedAt: new Date(),
+          isActive: true,
+          emailVerified: false,
+        });
+      }).toThrow("Invalid email format");
+    });
+  });
+
+  describe("toPlainObject()", () => {
+    it("should return a plain object without sensitive data", () => {
+      const now = new Date();
+      const user = new User(
+        validUserId,
+        validEmail,
+        validName,
+        validPassword,
+        now,
+        now,
+        true,
+        true
+      );
+
+      const plain = user.toPlainObject();
+
+      expect(plain).toEqual({
+        id: validUserId,
+        email: validEmail.value,
+        name: validName,
+        createdAt: now,
+        updatedAt: now,
+        isActive: true,
+        emailVerified: true,
+      });
+    });
+
+    it("should not include passwordHash in plain object", () => {
+      const user = User.create(
+        validUserId,
+        validEmail.value,
+        validName,
+        validPassword.hash
+      );
+
+      const plain = user.toPlainObject();
+
+      expect(plain).not.toHaveProperty("passwordHash");
+      expect(plain).not.toHaveProperty("password");
