+/**
+ * Password Value Object Tests (Domain Layer)
+ * 
+ * Tests the Password value object including:
+ * - Validation (bcrypt format validation)
+ * - Hash checking
+ * - Plaintext detection
+ */
+
+import { describe, it, expect } from "vitest";
+import { Password } from "./password";
+
+describe("Password Value Object", () => {
+  // Valid bcrypt hash (60 chars: $2b$10$ + 22 salt + 31 hash)
+  const validBcryptHash = "$2b$10$REDACTED";
+
+  describe("constructor validation", () => {
+    it("should create password with valid bcrypt hash", () => {
+      const password = new Password(validBcryptHash);
+      expect(password.hash).toBe(validBcryptHash);
+    });
+
+    it("should throw error for empty hash", () => {
+      expect(() => new Password("")).toThrow("Password hash cannot be empty");
+    });
+
+    it("should throw error for whitespace-only hash", () => {
+      expect(() => new Password("   ")).toThrow("Password hash cannot be empty");
+    });
+
+    it("should throw error for non-bcrypt hash", () => {
+      expect(() => new Password("plaintext-password")).toThrow(
+        "Password must be a valid bcrypt hash"
+      );
+    });
+
+    it("should throw error for hash without bcrypt prefix", () => {
+      expect(() => new Password("REDACTED")).toThrow(
+        "Password must be a valid bcrypt hash"
+      );
+    });
+
+    it("should throw error for incomplete bcrypt hash", () => {
+      expect(() => new Password("$2b$10$short")).toThrow(
+        "Password must be a valid bcrypt hash"
+      );
+    });
+  });
+
+  describe("bcrypt version support", () => {
+    it("should accept $2a$ bcrypt version", () => {
+      const hash = "$2a$10$REDACTED";
+      const password = new Password(hash);
+      expect(password.hash).toBe(hash);
+    });
+
+    it("should accept $2b$ bcrypt version", () => {
+      const hash = "$2b$10$REDACTED";
+      const password = new Password(hash);
+      expect(password.hash).toBe(hash);
+    });
+
+    it("should accept $2y$ bcrypt version", () => {
+      const hash = "$2y$10$REDACTED";
+      const password = new Password(hash);
+      expect(password.hash).toBe(hash);
+    });
+
+    it("should reject unsupported version like $3$", () => {
+      const hash = "$3$10$REDACTED";
+      expect(() => new Password(hash)).toThrow("Password must be a valid bcrypt hash");
+    });
+  });
+
+  describe("toString()", () => {
+    it("should return [REDACTED] to prevent accidental logging", () => {
+      const password = new Password(validBcryptHash);
+      expect(password.toString()).toBe("[REDACTED]");
+    });
+
+    it("should not expose hash in string interpolation", () => {
+      const password = new Password(validBcryptHash);
+      const message = `Password: ${password}`;
+      expect(message).toBe("Password: [REDACTED]");
+    });
+
+    it("should not expose hash in template literals", () => {
+      const password = new Password(validBcryptHash);
+      const message = `${password}`;
+      expect(message).toBe("[REDACTED]");
+    });
+  });
+
+  describe("isPlaintext()", () => {
+    it("should return false for bcrypt hash starting with $2a$", () => {
+      const hash = "$2a$10$REDACTED";
+      expect(Password.isPlaintext(hash)).toBe(false);
+    });
+
+    it("should return false for bcrypt hash starting with $2b$", () => {
+      const hash = "$2b$10$REDACTED";
+      expect(Password.isPlaintext(hash)).toBe(false);
+    });
+
+    it("should return true for plaintext password", () => {
+      expect(Password.isPlaintext("mypassword123")).toBe(true);
+    });
+
+    it("should return true for empty string", () => {
+      expect(Password.isPlaintext("")).toBe(true);
+    });
+
+    it("should return true for string not starting with $2", () => {
+      expect(Password.isPlaintext("$1$somehash")).toBe(true);
+    });
+
+    it("should return true for random string", () => {
+      expect(Password.isPlaintext("random-string-12345")).toBe(true);
+    });
+  });
+
+  describe("immutability", () => {
+    it("should declare hash property as readonly", () => {
+      const password = new Password(validBcryptHash);
+      // TypeScript prevents modification at compile time
+      // At runtime, readonly doesn't prevent modification, but the property
+      // is declared as readonly in the class definition
+      expect(password).toHaveProperty("hash");
+      expect(typeof password.hash).toBe("string");
+    });
+  });
+});

