      errorMessage: "FAILED_TO_SIGN_UP",  
    });
  }

  signIn(signInDTO: SignInDTO): Promise<{ token: string; }> {
    return tryCatch({
      ctx: async () => {
        await this.createToken
        const token = ID.TokenId();
        return { token };
      },
      errorMessage: "FAILED_TO_SIGN_IN",
    });
  }
}

