/**
 * User Entity Tests
 * 
 * Tests the User aggregate including:
 * - Factory methods (create, fromDatabase)
 * - Business rules (canAuthenticate, isFullyVerified)
 * - Data serialization (toPlainObject)
 * - Value object encapsulation (Email, Password)
 */

import { describe, it, expect, beforeEach } from "vitest";
import { User } from "./user";
import { Email } from "../value-objects/email";
import { Password } from "../value-objects/password";

describe("User Entity", () => {
  let validEmail: Email;
  let validPassword: Password;
  const validUserId = "user_12345";
  const validName = "John Doe";

  beforeEach(() => {
    validEmail = new Email("john@example.com");
    validPassword = new Password("$2b$10$REDACTED");
  });

  describe("constructor", () => {
    it("should create a user with all properties", () => {
      const now = new Date();
      const user = new User(
        validUserId,
        validEmail,
        validName,
        validPassword,
        now,
        now,
        true,
        false
      );

      expect(user.id).toBe(validUserId);
      expect(user.email).toBe(validEmail);
      expect(user.name).toBe(validName);
      expect(user.passwordHash).toBe(validPassword);
      expect(user.createdAt).toBe(now);
      expect(user.updatedAt).toBe(now);
      expect(user.isActive).toBe(true);
      expect(user.emailVerified).toBe(false);
    });

    it("should have default values for isActive (true) and emailVerified (false)", () => {
      const now = new Date();
      const user = new User(
        validUserId,
        validEmail,
        validName,
        validPassword,
        now,
        now
      );

      expect(user.isActive).toBe(true);
      expect(user.emailVerified).toBe(false);
    });
  });

  describe("canAuthenticate()", () => {
    it("should return true when user is active", () => {
      const user = User.create(
        validUserId,
        validEmail.value,
        validName,
        validPassword.hash
      );

      expect(user.canAuthenticate()).toBe(true);
    });

    it("should return false when user is inactive", () => {
      const now = new Date();
      const user = new User(
        validUserId,
        validEmail,
        validName,
        validPassword,
        now,
        now,
        false, // isActive = false
        false
      );

      expect(user.canAuthenticate()).toBe(false);
    });
  });

  describe("isFullyVerified()", () => {
    it("should return true when user is active and email verified", () => {
      const now = new Date();
      const user = new User(
        validUserId,
        validEmail,
        validName,
        validPassword,
        now,
        now,
        true, // isActive = true
        true  // emailVerified = true
      );

      expect(user.isFullyVerified()).toBe(true);
    });

    it("should return false when user is inactive but email verified", () => {
      const now = new Date();
      const user = new User(
        validUserId,
        validEmail,
        validName,
        validPassword,
        now,
        now,
        false, // isActive = false
        true   // emailVerified = true
      );

      expect(user.isFullyVerified()).toBe(false);
    });

    it("should return false when user is active but email not verified", () => {
      const now = new Date();
      const user = new User(
        validUserId,
        validEmail,
        validName,
        validPassword,
        now,
        now,
        true,  // isActive = true
        false  // emailVerified = false
      );

      expect(user.isFullyVerified()).toBe(false);
    });

    it("should return false when user is inactive and email not verified", () => {
      const now = new Date();
      const user = new User(
        validUserId,
        validEmail,
        validName,
        validPassword,
        now,
        now,
        false, // isActive = false
        false  // emailVerified = false
      );

      expect(user.isFullyVerified()).toBe(false);
    });
  });

  describe("create() factory method", () => {
    it("should create a new user with default values", () => {
      const user = User.create(
        validUserId,
        validEmail.value,
        validName,
        validPassword.hash
      );

      expect(user.id).toBe(validUserId);
      expect(user.email.value).toBe(validEmail.value);
      expect(user.name).toBe(validName);
      expect(user.passwordHash.hash).toBe(validPassword.hash);
      expect(user.isActive).toBe(true);
      expect(user.emailVerified).toBe(false);
    });

    it("should create email value object from string", () => {
      const user = User.create(
        validUserId,
        "test@example.com",
        validName,
        validPassword.hash
      );

      expect(user.email).toBeInstanceOf(Email);
      expect(user.email.value).toBe("test@example.com");
    });

    it("should create password value object from hash", () => {
      const user = User.create(
        validUserId,
        validEmail.value,
        validName,
        validPassword.hash
      );

      expect(user.passwordHash).toBeInstanceOf(Password);
      expect(user.passwordHash.hash).toBe(validPassword.hash);
    });

    it("should set createdAt and updatedAt to current time", () => {
      const beforeCreate = new Date();
      const user = User.create(
        validUserId,
        validEmail.value,
        validName,
        validPassword.hash
      );
      const afterCreate = new Date();

      expect(user.createdAt.getTime()).toBeGreaterThanOrEqual(beforeCreate.getTime());
      expect(user.createdAt.getTime()).toBeLessThanOrEqual(afterCreate.getTime());
      expect(user.updatedAt.getTime()).toBeGreaterThanOrEqual(beforeCreate.getTime());
      expect(user.updatedAt.getTime()).toBeLessThanOrEqual(afterCreate.getTime());
    });

    it("should throw if email is invalid", () => {
      expect(() => {
        User.create(
          validUserId,
          "invalid-email",
          validName,
          validPassword.hash
        );
      }).toThrow("Invalid email format");
    });

    it("should throw if password hash is invalid", () => {
      expect(() => {
        User.create(
          validUserId,
          validEmail.value,
          validName,
          "not-a-bcrypt-hash"
        );
      }).toThrow("Password must be a valid bcrypt hash");
    });
  });

  describe("fromDatabase() factory method", () => {
    it("should reconstruct user from database data", () => {
      const createdAt = new Date("2024-01-01T00:00:00Z");
      const updatedAt = new Date("2024-01-02T00:00:00Z");

      const user = User.fromDatabase({
        id: validUserId,
        email: validEmail.value,
        name: validName,
        passwordHash: validPassword.hash,
        createdAt,
        updatedAt,
        isActive: true,
        emailVerified: true,
      });

      expect(user.id).toBe(validUserId);
      expect(user.email.value).toBe(validEmail.value);
      expect(user.name).toBe(validName);
      expect(user.passwordHash.hash).toBe(validPassword.hash);
      expect(user.createdAt).toBe(createdAt);
      expect(user.updatedAt).toBe(updatedAt);
      expect(user.isActive).toBe(true);
      expect(user.emailVerified).toBe(true);
    });

    it("should preserve timestamps from database", () => {
      const createdAt = new Date("2023-06-15T10:30:00Z");
      const updatedAt = new Date("2024-01-20T15:45:30Z");

      const user = User.fromDatabase({
        id: validUserId,
        email: validEmail.value,
        name: validName,
        passwordHash: validPassword.hash,
        createdAt,
        updatedAt,
        isActive: true,
        emailVerified: false,
      });

      expect(user.createdAt).toEqual(createdAt);
      expect(user.updatedAt).toEqual(updatedAt);
    });

    it("should throw if email in data is invalid", () => {
      expect(() => {
        User.fromDatabase({
          id: validUserId,
          email: "invalid-email",
          name: validName,
          passwordHash: validPassword.hash,
          createdAt: new Date(),
          updatedAt: new Date(),
          isActive: true,
          emailVerified: false,
        });
      }).toThrow("Invalid email format");
    });
  });

  describe("toPlainObject()", () => {
    it("should return a plain object without sensitive data", () => {
      const now = new Date();
      const user = new User(
        validUserId,
        validEmail,
        validName,
        validPassword,
        now,
        now,
        true,
        true
      );

      const plain = user.toPlainObject();

      expect(plain).toEqual({
        id: validUserId,
        email: validEmail.value,
        name: validName,
        createdAt: now,
        updatedAt: now,
        isActive: true,
        emailVerified: true,
      });
    });

    it("should not include passwordHash in plain object", () => {
      const user = User.create(
        validUserId,
        validEmail.value,
        validName,
        validPassword.hash
      );

      const plain = user.toPlainObject();

      expect(plain).not.toHaveProperty("passwordHash");
      expect(plain).not.toHaveProperty("password");
    });

    it("should be JSON serializable", () => {
      const user = User.create(
        validUserId,
        validEmail.value,
        validName,
        validPassword.hash
      );

      const plain = user.toPlainObject();
      const json = JSON.stringify(plain);
      const parsed = JSON.parse(json);

      expect(parsed.id).toBe(validUserId);
      expect(parsed.email).toBe(validEmail.value);
      expect(parsed.name).toBe(validName);
      expect(parsed.isActive).toBe(true);
      expect(parsed.emailVerified).toBe(false);
    });
  });

  describe("immutability", () => {
    it("should not allow modifying user properties", () => {
      const user = User.create(
        validUserId,
        validEmail.value,
        validName,
        validPassword.hash
      );

      // Attempting to modify properties should either fail or be ignored
      expect(() => {
        (user as any).id = "modified";
      }).not.toThrow(); // TypeScript prevents this at compile time

      expect(user.id).toBe(validUserId);
    });
  });
});

/**
 * Email Value Object Tests
 * 
 * Tests the Email value object including:
 * - Validation (valid formats, empty, too long)
 * - Normalization (lowercase, trimming)
 * - Equality comparison
 */

import { describe, it, expect } from "vitest";
import { Email } from "./email";

describe("Email Value Object", () => {
  describe("constructor validation", () => {
    it("should create email with valid format", () => {
      const email = new Email("john@example.com");
      expect(email.value).toBe("john@example.com");
    });

    it("should throw error for empty email", () => {
      expect(() => new Email("")).toThrow("Email cannot be empty");
    });

    it("should throw error for whitespace-only email", () => {
      expect(() => new Email("   ")).toThrow("Email cannot be empty");
    });

    it("should throw error for email without @", () => {
      expect(() => new Email("johnexample.com")).toThrow("Invalid email format");
    });

    it("should throw error for email without domain", () => {
      expect(() => new Email("john@")).toThrow("Invalid email format");
    });

    it("should throw error for email without local part", () => {
      expect(() => new Email("@example.com")).toThrow("Invalid email format");
    });

    it("should throw error for email without TLD", () => {
      expect(() => new Email("john@example")).toThrow("Invalid email format");
    });

    it("should throw error for email with space", () => {
      expect(() => new Email("john doe@example.com")).toThrow("Invalid email format");
    });

    it("should throw error for email with multiple @ symbols", () => {
      expect(() => new Email("john@@example.com")).toThrow("Invalid email format");
    });

    it("should throw error for email that is too long (>254 chars)", () => {
      const longEmail = "a".repeat(250) + "@example.com";
      expect(() => new Email(longEmail)).toThrow("Email is too long");
    });

    it("should accept valid email at max length (254 chars)", () => {
      // RFC 5321: max email length is 254 characters
      const maxEmail = "a".repeat(240) + "@example.com";
      const email = new Email(maxEmail);
      expect(email.value).toBe(maxEmail);
    });
  });

  describe("normalization", () => {
    it("should convert to lowercase", () => {
      const email = new Email("John@Example.COM");
      expect(email.value).toBe("john@example.com");
    });

    it("should trim whitespace", () => {
      const email = new Email("  john@example.com  ");
      expect(email.value).toBe("john@example.com");
    });

    it("should trim and lowercase", () => {
      const email = new Email("  JOHN@EXAMPLE.COM  ");
      expect(email.value).toBe("john@example.com");
    });
  });

  describe("equals()", () => {
    it("should return true for equal emails", () => {
      const email1 = new Email("john@example.com");
      const email2 = new Email("john@example.com");
      expect(email1.equals(email2)).toBe(true);
    });

    it("should return true for emails with different cases that normalize to same value", () => {
      const email1 = new Email("John@Example.COM");
      const email2 = new Email("JOHN@EXAMPLE.COM");
      expect(email1.equals(email2)).toBe(true);
    });

    it("should return false for different emails", () => {
      const email1 = new Email("john@example.com");
      const email2 = new Email("jane@example.com");
      expect(email1.equals(email2)).toBe(false);
    });

    it("should return false for emails with different domains", () => {
      const email1 = new Email("john@example.com");
      const email2 = new Email("john@different.com");
      expect(email1.equals(email2)).toBe(false);
    });
  });

  describe("toString()", () => {
    it("should return the email value", () => {
      const email = new Email("john@example.com");
      expect(email.toString()).toBe("john@example.com");
    });

    it("should work in string interpolation", () => {
      const email = new Email("john@example.com");
      const message = `Email: ${email}`;
      expect(message).toBe("Email: john@example.com");
    });
  });

  describe("edge cases", () => {
    it("should accept valid email with numbers", () => {
      const email = new Email("john123@example456.com");
      expect(email.value).toBe("john123@example456.com");
    });

    it("should accept valid email with dots in local part", () => {
      const email = new Email("john.doe@example.com");
      expect(email.value).toBe("john.doe@example.com");
    });

    it("should accept valid email with plus addressing", () => {
      const email = new Email("john+tag@example.com");
      expect(email.value).toBe("john+tag@example.com");
    });

    it("should accept valid email with hyphens in domain", () => {
      const email = new Email("john@my-example.com");
      expect(email.value).toBe("john@my-example.com");
    });

    it("should accept subdomain emails", () => {
      const email = new Email("john@subdomain.example.com");
      expect(email.value).toBe("john@subdomain.example.com");
    });
  });
});

/**
 * Password Value Object Tests (Domain Layer)
 * 
 * Tests the Password value object including:
 * - Validation (bcrypt format validation)
 * - Hash checking
 * - Plaintext detection
 */

import { describe, it, expect } from "vitest";
import { Password } from "./password";

describe("Password Value Object", () => {
  const validBcryptHash = "$2b$10$REDACTED";

  describe("constructor validation", () => {
    it("should create password with valid bcrypt hash", () => {
      const password = new Password(validBcryptHash);
      expect(password.hash).toBe(validBcryptHash);
    });

    it("should throw error for empty hash", () => {
      expect(() => new Password("")).toThrow("Password hash cannot be empty");
    });

    it("should throw error for whitespace-only hash", () => {
      expect(() => new Password("   ")).toThrow("Password hash cannot be empty");
    });

    it("should throw error for non-bcrypt hash", () => {
      expect(() => new Password("plaintext-password")).toThrow(
        "Password must be a valid bcrypt hash"
      );
    });

    it("should throw error for hash without bcrypt prefix", () => {
      expect(() => new Password("REDACTED")).toThrow(
        "Password must be a valid bcrypt hash"
      );
    });

    it("should throw error for incomplete bcrypt hash", () => {
      expect(() => new Password("$2b$10$short")).toThrow(
        "Password must be a valid bcrypt hash"
      );
    });
  });

  describe("bcrypt version support", () => {
    it("should accept $2a$ bcrypt version", () => {
      const hash = "$2a$10$REDACTED";
      const password = new Password(hash);
      expect(password.hash).toBe(hash);
    });

    it("should accept $2b$ bcrypt version", () => {
      const hash = "$2b$10$REDACTED";
      const password = new Password(hash);
      expect(password.hash).toBe(hash);
    });

    it("should accept $2x$ bcrypt version", () => {
      const hash = "$2x$10$REDACTED";
      const password = new Password(hash);
      expect(password.hash).toBe(hash);
    });

    it("should accept $2y$ bcrypt version", () => {
      const hash = "$2y$10$REDACTED";
      const password = new Password(hash);
      expect(password.hash).toBe(hash);
    });

    it("should reject unsupported version like $3$", () => {
      const hash = "$3$10$REDACTED";
      expect(() => new Password(hash)).toThrow("Password must be a valid bcrypt hash");
    });
  });

  describe("toString()", () => {
    it("should return [REDACTED] to prevent accidental logging", () => {
      const password = new Password(validBcryptHash);
      expect(password.toString()).toBe("[REDACTED]");
    });

    it("should not expose hash in string interpolation", () => {
      const password = new Password(validBcryptHash);
      const message = `Password: ${password}`;
      expect(message).toBe("Password: [REDACTED]");
    });

    it("should not expose hash in template literals", () => {
      const password = new Password(validBcryptHash);
      const message = `${password}`;
      expect(message).toBe("[REDACTED]");
    });
  });

  describe("isPlaintext()", () => {
    it("should return false for bcrypt hash starting with $2a$", () => {
      const hash = "$2a$10$REDACTED";
      expect(Password.isPlaintext(hash)).toBe(false);
    });

    it("should return false for bcrypt hash starting with $2b$", () => {
      const hash = "$2b$10$REDACTED";
      expect(Password.isPlaintext(hash)).toBe(false);
    });

    it("should return true for plaintext password", () => {
      expect(Password.isPlaintext("mypassword123")).toBe(true);
    });

    it("should return true for empty string", () => {
      expect(Password.isPlaintext("")).toBe(true);
    });

    it("should return true for string not starting with $2", () => {
      expect(Password.isPlaintext("$1$somehash")).toBe(true);
    });

    it("should return true for random string", () => {
      expect(Password.isPlaintext("random-string-12345")).toBe(true);
    });
  });

  describe("immutability", () => {
    it("should not allow modifying hash property", () => {
      const password = new Password(validBcryptHash);
      expect(() => {
        (password as any).hash = "modified";
      }).not.toThrow(); // readonly prevents modification at runtime

      expect(password.hash).toBe(validBcryptHash);
    });
  });
});

