/**
 * Sign Up Use Case Tests
 * 
 * Tests the sign-up business logic including:
 * - Valid registration
 * - Email uniqueness validation
 * - Input validation
 * - Error handling
 * - Password hashing integration
 */

import { describe, it, expect, beforeEach, vi } from "vitest";
import { SignUpUseCase } from "./sign-up.use-case";
import { InMemoryUserRepository } from "../../adapters/repositories/in-memory-user-repository";
import { MockPasswordHasher } from "../../adapters/password-adapters";
import type { IPasswordHasher } from "./sign-up.use-case";
import type { IUserRepository } from "../../domain/interfaces/user-repository.interface";

describe("SignUpUseCase", () => {
  let useCase: SignUpUseCase;
  let userRepository: IUserRepository;
  let passwordHasher: IPasswordHasher;

  beforeEach(() => {
    userRepository = new InMemoryUserRepository();
    passwordHasher = new MockPasswordHasher();
    useCase = new SignUpUseCase(userRepository, passwordHasher);
  });

  describe("successful registration", () => {
    it("should register a new user with valid input", async () => {
      const request = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(true);
      expect(result.userId).toBeDefined();
      expect(result.email).toBe("john@example.com");
      expect(result.error).toBeUndefined();
    });

    it("should hash the password before storage", async () => {
      const hasherSpy = vi.spyOn(passwordHasher, "hash");

      const request = {
        email: "test@example.com",
        password: "mypassword",
        name: "Test User",
      };

      await useCase.execute(request);

      expect(hasherSpy).toHaveBeenCalledWith("mypassword");
    });

    it("should store user in repository", async () => {
      const request = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const result = await useCase.execute(request);

      if (result.success && result.userId) {
        const savedUser = await userRepository.findById(result.userId);
        expect(savedUser).toBeDefined();
        expect(savedUser?.email.value).toBe("john@example.com");
        expect(savedUser?.name).toBe("John Doe");
      }
    });

    it("should create user with active status", async () => {
      const request = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const result = await useCase.execute(request);

      if (result.success && result.userId) {
        const savedUser = await userRepository.findById(result.userId);
        expect(savedUser?.isActive).toBe(true);
      }
    });

    it("should create user with unverified email", async () => {
      const request = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const result = await useCase.execute(request);

      if (result.success && result.userId) {
        const savedUser = await userRepository.findById(result.userId);
        expect(savedUser?.emailVerified).toBe(false);
      }
    });

    it("should normalize email to lowercase", async () => {
      const request = {
        email: "John@EXAMPLE.COM",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(true);
      expect(result.email).toBe("john@example.com");
    });
  });

  describe("input validation", () => {
    it("should fail if email is missing", async () => {
      const request = {
        email: "",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Email, password, and name are required");
    });

    it("should fail if password is missing", async () => {
      const request = {
        email: "john@example.com",
        password: "",
        name: "John Doe",
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Email, password, and name are required");
    });

    it("should fail if name is missing", async () => {
      const request = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "",
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Email, password, and name are required");
    });

    it("should fail if email format is invalid", async () => {
      const request = {
        email: "invalid-email",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toBeDefined();
    });
  });

  describe("email uniqueness", () => {
    it("should fail if email already exists", async () => {
      const request = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      // First registration should succeed
      const firstResult = await useCase.execute(request);
      expect(firstResult.success).toBe(true);

      // Second registration with same email should fail
      const secondResult = await useCase.execute(request);
      expect(secondResult.success).toBe(false);
      expect(secondResult.error).toContain("Email already registered");
    });

    it("should check email case-insensitively", async () => {
      const request1 = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const request2 = {
        email: "JOHN@EXAMPLE.COM",
        password: "DifferentPassword123",
        name: "Another John",
      };

      // First registration
      const firstResult = await useCase.execute(request1);
      expect(firstResult.success).toBe(true);

      // Second registration with different case should fail
      const secondResult = await useCase.execute(request2);
      expect(secondResult.success).toBe(false);
      expect(secondResult.error).toContain("Email already registered");
    });

    it("should allow different emails", async () => {
      const request1 = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const request2 = {
        email: "jane@example.com",
        password: "SecurePassword123",
        name: "Jane Doe",
      };

      const firstResult = await useCase.execute(request1);
      expect(firstResult.success).toBe(true);

      const secondResult = await useCase.execute(request2);
      expect(secondResult.success).toBe(true);
    });
  });

  describe("error handling", () => {
    it("should handle repository errors gracefully", async () => {
      const failingRepository = {
        async findById() {
          throw new Error("Database error");
        },
        async findByEmail() {
          throw new Error("Database error");
        },
        async save() {
          throw new Error("Database error");
        },
        async update() {
          throw new Error("Database error");
        },
        async emailExists() {
          throw new Error("Database error");
        },
        async delete() {
          throw new Error("Database error");
        },
      };

      const useCaseWithFailingRepo = new SignUpUseCase(
        failingRepository as any,
        passwordHasher
      );

      const request = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const result = await useCaseWithFailingRepo.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Database error");
    });

    it("should handle hasher errors gracefully", async () => {
      const failingHasher = {
        async hash() {
          throw new Error("Hashing failed");
        },
      };

      const useCaseWithFailingHasher = new SignUpUseCase(
        userRepository,
        failingHasher as any
      );

      const request = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const result = await useCaseWithFailingHasher.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Hashing failed");
    });
  });

  describe("user ID generation", () => {
    it("should generate unique user IDs", async () => {
      const request1 = {
        email: "user1@example.com",
        password: "SecurePassword123",
        name: "User One",
      };

      const request2 = {
        email: "user2@example.com",
        password: "SecurePassword123",
        name: "User Two",
      };

      const result1 = await useCase.execute(request1);
      const result2 = await useCase.execute(request2);

      expect(result1.success).toBe(true);
      expect(result2.success).toBe(true);
      expect(result1.userId).not.toBe(result2.userId);
    });

    it("should return user ID in response", async () => {
      const request = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(true);
      expect(result.userId).toBeDefined();
      expect(typeof result.userId).toBe("string");
      expect(result.userId).toBeTruthy();
    });
  });
});

/**
 * Sign In Use Case Tests
 * 
 * Tests the sign-in business logic including:
 * - Successful authentication
 * - Invalid credentials
 * - Inactive users
 * - Session creation
 * - Error handling
 */

import { describe, it, expect, beforeEach, vi } from "vitest";
import { SignInUseCase } from "./sign-in.use-case";
import { InMemoryUserRepository } from "../../adapters/repositories/in-memory-user-repository";
import { MockPasswordHasher, MockPasswordVerifier } from "../../adapters/password-adapters";
import type { IPasswordVerifier, ISessionFactory } from "./sign-in.use-case";
import { User } from "../../domain/entities/user";
import { Email } from "../../domain/value-objects/email";
import { Password } from "../../domain/value-objects/password";

describe("SignInUseCase", () => {
  let useCase: SignInUseCase;
  let userRepository: InMemoryUserRepository;
  let passwordVerifier: IPasswordVerifier;
  let sessionFactory: ISessionFactory;

  // Valid test user
  const testUserEmail = "john@example.com";
  const testUserPassword = "SecurePassword123";
  const testUserPasswordHash = "$2b$10$mock12charactersofmockedhash00000000000000000000";
  const testUserId = "user_test_123";

  beforeEach(async () => {
    userRepository = new InMemoryUserRepository();
    passwordVerifier = new MockPasswordVerifier();
    sessionFactory = {
      create: async (userId: string) => `session_token_${userId}`,
    };

    useCase = new SignInUseCase(userRepository, passwordVerifier, sessionFactory);

    // Create a test user
    const testUser = User.create(
      testUserId,
      testUserEmail,
      "John Doe",
      testUserPasswordHash
    );
    await userRepository.save(testUser);
  });

  describe("successful authentication", () => {
    it("should authenticate user with valid credentials", async () => {
      const request = {
        email: testUserEmail,
        password: testUserPassword,
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(true);
      expect(result.userId).toBe(testUserId);
      expect(result.email).toBe(testUserEmail);
      expect(result.sessionToken).toBeDefined();
    });

    it("should return session token", async () => {
      const request = {
        email: testUserEmail,
        password: testUserPassword,
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(true);
      expect(result.sessionToken).toBeTruthy();
      expect(typeof result.sessionToken).toBe("string");
    });

    it("should verify password", async () => {
      const verifierSpy = vi.spyOn(passwordVerifier, "verify");

      const request = {
        email: testUserEmail,
        password: testUserPassword,
      };

      await useCase.execute(request);

      expect(verifierSpy).toHaveBeenCalledWith(
        testUserPassword,
        testUserPasswordHash
      );
    });

    it("should call session factory", async () => {
      const sessionFactorySpy = vi.spyOn(sessionFactory, "create");

      const request = {
        email: testUserEmail,
        password: testUserPassword,
      };

      await useCase.execute(request);

      expect(sessionFactorySpy).toHaveBeenCalledWith(testUserId);
    });
  });

  describe("input validation", () => {
    it("should fail if email is missing", async () => {
      const request = {
        email: "",
        password: testUserPassword,
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Email and password are required");
    });

    it("should fail if password is missing", async () => {
      const request = {
        email: testUserEmail,
        password: "",
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Email and password are required");
    });

    it("should fail if both email and password are missing", async () => {
      const request = {
        email: "",
        password: "",
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Email and password are required");
    });
  });

  describe("user not found", () => {
    it("should fail with invalid email", async () => {
      const request = {
        email: "nonexistent@example.com",
        password: testUserPassword,
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Invalid email or password");
    });

    it("should not reveal if user exists", async () => {
      const nonexistentRequest = {
        email: "nonexistent@example.com",
        password: "anypassword",
      };

      const invalidPasswordRequest = {
        email: testUserEmail,
        password: "wrongpassword",
      };

      const result1 = await useCase.execute(nonexistentRequest);
      const result2 = await useCase.execute(invalidPasswordRequest);

      // Both should return the same error message for security
      expect(result1.error).toContain("Invalid email or password");
      expect(result2.error).toContain("Invalid email or password");
    });
  });

  describe("invalid password", () => {
    it("should fail with wrong password", async () => {
      const request = {
        email: testUserEmail,
        password: "WrongPassword123",
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Invalid email or password");
    });
  });

  describe("user account status", () => {
    it("should fail if user is inactive", async () => {
      const inactiveUser = new User(
        "inactive_user_id",
        new Email("inactive@example.com"),
        "Inactive User",
        new Password(testUserPasswordHash),
        new Date(),
        new Date(),
        false, // isActive = false
        false
      );

      await userRepository.save(inactiveUser);

      const request = {
        email: "inactive@example.com",
        password: testUserPassword,
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Account is not active");
    });

    it("should succeed if user is active", async () => {
      const request = {
        email: testUserEmail,
        password: testUserPassword,
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(true);
    });
  });

  describe("error handling", () => {
    it("should handle repository errors gracefully", async () => {
      const failingRepository = {
        async findById() {
          throw new Error("Database error");
        },
        async findByEmail() {
          throw new Error("Database error");
        },
        async save() {
          throw new Error("Database error");
        },
        async update() {
          throw new Error("Database error");
        },
        async emailExists() {
          throw new Error("Database error");
        },
        async delete() {
          throw new Error("Database error");
        },
      };

      const useCaseWithFailingRepo = new SignInUseCase(
        failingRepository as any,
        passwordVerifier,
        sessionFactory
      );

      const request = {
        email: testUserEmail,
        password: testUserPassword,
      };

      const result = await useCaseWithFailingRepo.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Database error");
    });

    it("should handle verifier errors gracefully", async () => {
      const failingVerifier = {
        async verify() {
          throw new Error("Verification failed");
        },
      };

      const useCaseWithFailingVerifier = new SignInUseCase(
        userRepository,
        failingVerifier as any,
        sessionFactory
      );

      const request = {
        email: testUserEmail,
        password: testUserPassword,
      };

      const result = await useCaseWithFailingVerifier.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Verification failed");
    });

    it("should handle session factory errors gracefully", async () => {
      const failingSessionFactory = {
        async create() {
          throw new Error("Session creation failed");
        },
      };

      const useCaseWithFailingFactory = new SignInUseCase(
        userRepository,
        passwordVerifier,
        failingSessionFactory as any
      );

      const request = {
        email: testUserEmail,
        password: testUserPassword,
      };

      const result = await useCaseWithFailingFactory.execute(request);

      expect(result.success).toBe(false);
      expect(result.error).toContain("Session creation failed");
    });
  });

  describe("case insensitivity", () => {
    it("should find user with different email case", async () => {
      const request = {
        email: "JOHN@EXAMPLE.COM",
        password: testUserPassword,
      };

      const result = await useCase.execute(request);

      expect(result.success).toBe(true);
      expect(result.email).toBe(testUserEmail);
    });
  });
});

