/**
 * InMemory User Repository Tests
 * 
 * Tests the in-memory repository adapter including:
 * - CRUD operations
 * - Email index
 * - Error handling
 * - Test helpers
 */

import { describe, it, expect, beforeEach } from "vitest";
import { InMemoryUserRepository } from "./in-memory-user-repository";
import { User } from "../../domain/entities/user";
import { Email } from "../../domain/value-objects/email";
import { Password } from "../../domain/value-objects/password";

describe("InMemoryUserRepository", () => {
  let repository: InMemoryUserRepository;
  const validPasswordHash = "$2b$10$REDACTED";

  beforeEach(() => {
    repository = new InMemoryUserRepository();
  });

  describe("save()", () => {
    it("should save a user", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      const saved = await repository.save(user);

      expect(saved).toEqual(user);
    });

    it("should throw error if email already exists", async () => {
      const user1 = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      const user2 = User.create(
        "user_2",
        "john@example.com",
        "Jane Doe",
        validPasswordHash
      );

      await repository.save(user1);

      await expect(() => repository.save(user2)).rejects.toThrow(
        "Email already exists"
      );
    });

    it("should be retrievable after save", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await repository.save(user);
      const retrieved = await repository.findById(user.id);

      expect(retrieved).toBeDefined();
      expect(retrieved?.id).toBe(user.id);
    });
  });

  describe("findById()", () => {
    it("should find a user by ID", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await repository.save(user);
      const found = await repository.findById(user.id);

      expect(found).toBeDefined();
      expect(found?.id).toBe(user.id);
      expect(found?.email.value).toBe("john@example.com");
    });

    it("should return null if user not found", async () => {
      const found = await repository.findById("nonexistent_id");
      expect(found).toBeNull();
    });
  });

  describe("findByEmail()", () => {
    it("should find a user by email", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await repository.save(user);
      const found = await repository.findByEmail("john@example.com");

      expect(found).toBeDefined();
      expect(found?.email.value).toBe("john@example.com");
    });

    it("should find user by email case-insensitively", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await repository.save(user);
      const found = await repository.findByEmail("JOHN@EXAMPLE.COM");

      expect(found).toBeDefined();
      expect(found?.email.value).toBe("john@example.com");
    });

    it("should return null if email not found", async () => {
      const found = await repository.findByEmail("nonexistent@example.com");
      expect(found).toBeNull();
    });
  });

  describe("emailExists()", () => {
    it("should return true if email exists", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await repository.save(user);
      const exists = await repository.emailExists("john@example.com");

      expect(exists).toBe(true);
    });

    it("should return true for email with different case", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await repository.save(user);
      const exists = await repository.emailExists("JOHN@EXAMPLE.COM");

      expect(exists).toBe(true);
    });

    it("should return false if email does not exist", async () => {
      const exists = await repository.emailExists("nonexistent@example.com");
      expect(exists).toBe(false);
    });
  });

  describe("update()", () => {
    it("should update an existing user", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await repository.save(user);

      // Create updated user
      const updatedUser = new User(
        user.id,
        user.email,
        "Jane Doe", // changed name
        user.passwordHash,
        user.createdAt,
        new Date(),
        user.isActive,
        user.emailVerified
      );

      const result = await repository.update(updatedUser);

      expect(result.name).toBe("Jane Doe");

      const retrieved = await repository.findById(user.id);
      expect(retrieved?.name).toBe("Jane Doe");
    });

    it("should throw error if user not found", async () => {
      const user = User.create(
        "nonexistent_id",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await expect(() => repository.update(user)).rejects.toThrow(
        "User not found"
      );
    });
  });

  describe("delete()", () => {
    it("should delete a user", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await repository.save(user);
      const deleted = await repository.delete(user.id);

      expect(deleted).toBe(true);

      const found = await repository.findById(user.id);
      expect(found).toBeNull();
    });

    it("should also remove from email index", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await repository.save(user);
      await repository.delete(user.id);

      const exists = await repository.emailExists("john@example.com");
      expect(exists).toBe(false);
    });

    it("should return false if user not found", async () => {
      const deleted = await repository.delete("nonexistent_id");
      expect(deleted).toBe(false);
    });
  });

  describe("getAllUsers() helper", () => {
    it("should return all users", async () => {
      const user1 = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      const user2 = User.create(
        "user_2",
        "jane@example.com",
        "Jane Doe",
        validPasswordHash
      );

      await repository.save(user1);
      await repository.save(user2);

      const allUsers = repository.getAllUsers();

      expect(allUsers).toHaveLength(2);
      expect(allUsers.find(u => u.id === user1.id)).toBeDefined();
      expect(allUsers.find(u => u.id === user2.id)).toBeDefined();
    });

    it("should return empty array when no users", () => {
      const allUsers = repository.getAllUsers();
      expect(allUsers).toEqual([]);
    });
  });

  describe("clear() helper", () => {
    it("should clear all users", async () => {
      const user1 = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      const user2 = User.create(
        "user_2",
        "jane@example.com",
        "Jane Doe",
        validPasswordHash
      );

      await repository.save(user1);
      await repository.save(user2);

      repository.clear();

      const allUsers = repository.getAllUsers();
      expect(allUsers).toHaveLength(0);
    });

    it("should reset email index", async () => {
      const user = User.create(
        "user_1",
        "john@example.com",
        "John Doe",
        validPasswordHash
      );

      await repository.save(user);
      repository.clear();

      const exists = await repository.emailExists("john@example.com");
      expect(exists).toBe(false);
    });
  });
});

/**
 * Password Adapters Tests
 * 
 * Tests the mock and null password adapters:
 * - MockPasswordHasher/Verifier (for testing)
 * - NullPasswordHasher/Verifier (for testing without real hashing)
 */

import { describe, it, expect } from "vitest";
import {
  MockPasswordHasher,
  MockPasswordVerifier,
  NullPasswordHasher,
  NullPasswordVerifier,
} from "./password-adapters";

describe("Password Adapters", () => {
  describe("MockPasswordHasher", () => {
    const hasher = new MockPasswordHasher();

    it("should hash a password", async () => {
      const plaintext = "mypassword";
      const hash = await hasher.hash(plaintext);

      expect(hash).toBeDefined();
      expect(typeof hash).toBe("string");
    });

    it("should create bcrypt-like hash format", async () => {
      const plaintext = "mypassword";
      const hash = await hasher.hash(plaintext);

      expect(hash).toMatch(/^\$2b\$10\$mock/);
    });

    it("should include password length in hash", async () => {
      const plaintext = "mypassword";
      const hash = await hasher.hash(plaintext);

      expect(hash).toContain(`mock${plaintext.length}characters`);
    });

    it("should produce consistent hashes", async () => {
      const plaintext = "mypassword";
      const hash1 = await hasher.hash(plaintext);
      const hash2 = await hasher.hash(plaintext);

      expect(hash1).toBe(hash2);
    });

    it("should produce different hashes for different passwords", async () => {
      const hash1 = await hasher.hash("password1");
      const hash2 = await hasher.hash("password2");

      expect(hash1).not.toBe(hash2);
    });
  });

  describe("MockPasswordVerifier", () => {
    const hasher = new MockPasswordHasher();
    const verifier = new MockPasswordVerifier();

    it("should verify correct password", async () => {
      const plaintext = "mypassword";
      const hash = await hasher.hash(plaintext);

      const isValid = await verifier.verify(plaintext, hash);

      expect(isValid).toBe(true);
    });

    it("should reject wrong password", async () => {
      const plaintext = "mypassword";
      const hash = await hasher.hash(plaintext);

      const isValid = await verifier.verify("wrongpassword", hash);

      expect(isValid).toBe(false);
    });

    it("should be sensitive to password length", async () => {
      const hash = await hasher.hash("short");

      const isValid = await verifier.verify("shorterpassword", hash);

      expect(isValid).toBe(false);
    });

    it("should work with the hasher", async () => {
      const password = "TestPassword123";
      const hash = await hasher.hash(password);
      const isValid = await verifier.verify(password, hash);

      expect(isValid).toBe(true);
    });
  });

  describe("NullPasswordHasher", () => {
    const hasher = new NullPasswordHasher();

    it("should return plaintext as hash (for testing)", async () => {
      const plaintext = "mypassword";
      const hash = await hasher.hash(plaintext);

      expect(hash).toBe(plaintext);
    });

    it("should preserve original password", async () => {
      const password = "ComplexPassword!@#123";
      const hash = await hasher.hash(password);

      expect(hash).toBe(password);
    });
  });

  describe("NullPasswordVerifier", () => {
    const hasher = new NullPasswordHasher();
    const verifier = new NullPasswordVerifier();

    it("should verify by string comparison (for testing)", async () => {
      const plaintext = "mypassword";
      const hash = await hasher.hash(plaintext);

      const isValid = await verifier.verify(plaintext, hash);

      expect(isValid).toBe(true);
    });

    it("should reject different passwords", async () => {
      const hash = "storedpassword";
      const isValid = await verifier.verify("differentpassword", hash);

      expect(isValid).toBe(false);
    });

    it("should be case-sensitive", async () => {
      const hash = "mypassword";
      const isValid = await verifier.verify("MyPassword", hash);

      expect(isValid).toBe(false);
    });
  });

  describe("Integration", () => {
    it("MockPasswordHasher should work with MockPasswordVerifier", async () => {
      const hasher = new MockPasswordHasher();
      const verifier = new MockPasswordVerifier();

      const password = "TestPassword123";
      const hash = await hasher.hash(password);
      const isValid = await verifier.verify(password, hash);

      expect(isValid).toBe(true);
    });

    it("NullPasswordHasher should work with NullPasswordVerifier", async () => {
      const hasher = new NullPasswordHasher();
      const verifier = new NullPasswordVerifier();

      const password = "TestPassword123";
      const hash = await hasher.hash(password);
      const isValid = await verifier.verify(password, hash);

      expect(isValid).toBe(true);
    });
  });
});

/**
 * Auth Controller Tests
 * 
 * Tests the HTTP controller layer including:
 * - Sign up endpoint
 * - Sign in endpoint
 * - Input validation
 * - Error responses
 * - Success responses
 */

import { describe, it, expect, beforeEach, vi } from "vitest";
import { AuthController } from "./auth.controller";
import { SignUpUseCase } from "../../use-cases/sign-up.use-case";
import { SignInUseCase } from "../../use-cases/sign-in.use-case";
import { InMemoryUserRepository } from "../repositories/in-memory-user-repository";
import { MockPasswordHasher, MockPasswordVerifier } from "../password-adapters";
import type { FastifyRequest, FastifyReply } from "fastify";

describe("AuthController", () => {
  let controller: AuthController;
  let mockRequest: Partial<FastifyRequest>;
  let mockReply: Partial<FastifyReply>;

  beforeEach(() => {
    const repository = new InMemoryUserRepository();
    const hasher = new MockPasswordHasher();
    const verifier = new MockPasswordVerifier();
    const sessionFactory = {
      create: async (userId: string) => `session_${userId}`,
    };

    const signUpUseCase = new SignUpUseCase(repository, hasher);
    const signInUseCase = new SignInUseCase(repository, verifier, sessionFactory);

    controller = new AuthController(signUpUseCase, signInUseCase);

    // Create mock request/reply
    mockRequest = {
      body: {},
    };

    mockReply = {
      status: vi.fn().mockReturnThis(),
      send: vi.fn(),
    };
  });

  describe("signUp()", () => {
    it("should return 201 on successful registration", async () => {
      mockRequest.body = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      await controller.signUp(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      expect(mockReply.status).toHaveBeenCalledWith(201);
      expect(mockReply.send).toHaveBeenCalled();

      const response = (mockReply.send as any).mock.calls[0][0];
      expect(response.ok).toBe(true);
      expect(response.data.userId).toBeDefined();
      expect(response.data.email).toBe("john@example.com");
    });

    it("should return 400 if email is invalid", async () => {
      mockRequest.body = {
        email: "invalid-email",
        password: "SecurePassword123",
        name: "John Doe",
      };

      await controller.signUp(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      expect(mockReply.status).toHaveBeenCalledWith(400);
      const response = (mockReply.send as any).mock.calls[0][0];
      expect(response.ok).toBe(false);
    });

    it("should return 400 if password is too short", async () => {
      mockRequest.body = {
        email: "john@example.com",
        password: "short",
        name: "John Doe",
      };

      await controller.signUp(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      expect(mockReply.status).toHaveBeenCalledWith(400);
      const response = (mockReply.send as any).mock.calls[0][0];
      expect(response.message).toContain("Validation failed");
    });

    it("should return 400 if name is empty", async () => {
      mockRequest.body = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "",
      };

      await controller.signUp(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      expect(mockReply.status).toHaveBeenCalledWith(400);
      const response = (mockReply.send as any).mock.calls[0][0];
      expect(response.message).toContain("Validation failed");
    });

    it("should return 400 if email already exists", async () => {
      mockRequest.body = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      // First registration
      await controller.signUp(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      // Reset mocks
      mockReply.status = vi.fn().mockReturnThis();
      mockReply.send = vi.fn();

      // Second registration with same email
      await controller.signUp(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      expect(mockReply.status).toHaveBeenCalledWith(400);
      const response = (mockReply.send as any).mock.calls[0][0];
      expect(response.error).toContain("Email already registered");
    });

    it("should include message in response", async () => {
      mockRequest.body = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      await controller.signUp(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      const response = (mockReply.send as any).mock.calls[0][0];
      expect(response.message).toBeDefined();
    });
  });

  describe("signIn()", () => {
    beforeEach(async () => {
      // Create a test user first
      mockRequest.body = {
        email: "john@example.com",
        password: "SecurePassword123",
        name: "John Doe",
      };

      mockReply.status = vi.fn().mockReturnThis();
      mockReply.send = vi.fn();

      const repository = new InMemoryUserRepository();
      const hasher = new MockPasswordHasher();
      const verifier = new MockPasswordVerifier();
      const sessionFactory = {
        create: async (userId: string) => `session_${userId}`,
      };

      const signUpUseCase = new SignUpUseCase(repository, hasher);
      const signInUseCase = new SignInUseCase(repository, verifier, sessionFactory);

      controller = new AuthController(signUpUseCase, signInUseCase);

      await controller.signUp(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );
    });

    it("should return 200 on successful sign in", async () => {
      mockReply.status = vi.fn().mockReturnThis();
      mockReply.send = vi.fn();

      mockRequest.body = {
        email: "john@example.com",
        password: "SecurePassword123",
      };

      await controller.signIn(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      expect(mockReply.status).toHaveBeenCalledWith(200);
      const response = (mockReply.send as any).mock.calls[0][0];
      expect(response.ok).toBe(true);
      expect(response.data.sessionToken).toBeDefined();
    });

    it("should return 401 with invalid password", async () => {
      mockReply.status = vi.fn().mockReturnThis();
      mockReply.send = vi.fn();

      mockRequest.body = {
        email: "john@example.com",
        password: "WrongPassword123",
      };

      await controller.signIn(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      expect(mockReply.status).toHaveBeenCalledWith(401);
      const response = (mockReply.send as any).mock.calls[0][0];
      expect(response.ok).toBe(false);
    });

    it("should return 401 with nonexistent email", async () => {
      mockReply.status = vi.fn().mockReturnThis();
      mockReply.send = vi.fn();

      mockRequest.body = {
        email: "nonexistent@example.com",
        password: "SecurePassword123",
      };

      await controller.signIn(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      expect(mockReply.status).toHaveBeenCalledWith(401);
    });

    it("should return 400 if email is invalid", async () => {
      mockReply.status = vi.fn().mockReturnThis();
      mockReply.send = vi.fn();

      mockRequest.body = {
        email: "invalid-email",
        password: "SecurePassword123",
      };

      await controller.signIn(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      expect(mockReply.status).toHaveBeenCalledWith(400);
      const response = (mockReply.send as any).mock.calls[0][0];
      expect(response.message).toContain("Validation failed");
    });

    it("should return session token in response", async () => {
      mockReply.status = vi.fn().mockReturnThis();
      mockReply.send = vi.fn();

      mockRequest.body = {
        email: "john@example.com",
        password: "SecurePassword123",
      };

      await controller.signIn(
        mockRequest as FastifyRequest,
        mockReply as FastifyReply
      );

      const response = (mockReply.send as any).mock.calls[0][0];
      expect(response.data.sessionToken).toBeTruthy();
      expect(typeof response.data.sessionToken).toBe("string");
    });
