/**
 * ID Service Tests
 * 
 * Tests the ID generation utility including:
 * - ID format
 * - Uniqueness
 * - Type safety
 */

import { describe, it, expect } from "vitest";
import { ID } from "./generate-id";

describe("ID Service", () => {
  describe("UserId()", () => {
    it("should generate a user ID", () => {
      const id = ID.UserId();
      expect(id).toBeDefined();
      expect(typeof id).toBe("string");
    });

    it("should start with 'user_' prefix", () => {
      const id = ID.UserId();
      expect(id).toMatch(/^user_/);
    });

    it("should generate unique IDs", () => {
      const id1 = ID.UserId();
      const id2 = ID.UserId();
      expect(id1).not.toBe(id2);
    });

    it("should contain UUID format after prefix", () => {
      const id = ID.UserId();
      const uuid = id.replace("user_", "");
      // UUID v4 format: xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx
      expect(uuid).toMatch(
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
      );
    });

    it("should generate multiple unique IDs", () => {
      const ids = Array.from({ length: 100 }, () => ID.UserId());
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(100);
    });
  });

  describe("SessionId()", () => {
    it("should generate a session ID", () => {
      const id = ID.SessionId();
      expect(id).toBeDefined();
      expect(typeof id).toBe("string");
    });

    it("should start with 'session_' prefix", () => {
      const id = ID.SessionId();
      expect(id).toMatch(/^session_/);
    });

    it("should generate unique IDs", () => {
      const id1 = ID.SessionId();
      const id2 = ID.SessionId();
      expect(id1).not.toBe(id2);
    });

    it("should contain UUID format after prefix", () => {
      const id = ID.SessionId();
      const uuid = id.replace("session_", "");
      expect(uuid).toMatch(
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
      );
    });
  });

  describe("AccountId()", () => {
    it("should generate an account ID", () => {
      const id = ID.AccountId();
      expect(id).toBeDefined();
      expect(typeof id).toBe("string");
    });

    it("should start with 'account_' prefix", () => {
      const id = ID.AccountId();
      expect(id).toMatch(/^account_/);
    });

    it("should generate unique IDs", () => {
      const id1 = ID.AccountId();
      const id2 = ID.AccountId();
      expect(id1).not.toBe(id2);
    });

    it("should contain UUID format after prefix", () => {
      const id = ID.AccountId();
      const uuid = id.replace("account_", "");
      expect(uuid).toMatch(
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
      );
    });
  });

  describe("TokenId()", () => {
    it("should generate a token ID", () => {
      const id = ID.TokenId();
      expect(id).toBeDefined();
      expect(typeof id).toBe("string");
    });

    it("should start with 'token_' prefix", () => {
      const id = ID.TokenId();
      expect(id).toMatch(/^token_/);
    });

    it("should generate unique IDs", () => {
      const id1 = ID.TokenId();
      const id2 = ID.TokenId();
      expect(id1).not.toBe(id2);
    });

    it("should contain UUID format after prefix", () => {
      const id = ID.TokenId();
      const uuid = id.replace("token_", "");
      expect(uuid).toMatch(
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
      );
    });
  });

  describe("cross-type uniqueness", () => {
    it("should generate different formats for different types", () => {
      const userId = ID.UserId();
      const sessionId = ID.SessionId();
      const accountId = ID.AccountId();
      const tokenId = ID.TokenId();

      expect(userId).toMatch(/^user_/);
      expect(sessionId).toMatch(/^session_/);
      expect(accountId).toMatch(/^account_/);
      expect(tokenId).toMatch(/^token_/);
    });

    it("should generate unique IDs across all types", () => {
      const ids = [
        ID.UserId(),
        ID.SessionId(),
        ID.AccountId(),
        ID.TokenId(),
      ];
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(4);
    });
  });

  describe("ID format consistency", () => {
    it("should have consistent format for user IDs", () => {
      const ids = Array.from({ length: 10 }, () => ID.UserId());
      ids.forEach((id) => {
        expect(id).toMatch(/^user_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
      });
    });

    it("should have consistent format for session IDs", () => {
      const ids = Array.from({ length: 10 }, () => ID.SessionId());
      ids.forEach((id) => {
        expect(id).toMatch(/^session_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
      });
    });

    it("should have consistent format for account IDs", () => {
      const ids = Array.from({ length: 10 }, () => ID.AccountId());
      ids.forEach((id) => {
        expect(id).toMatch(/^account_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
      });
    });

    it("should have consistent format for token IDs", () => {
      const ids = Array.from({ length: 10 }, () => ID.TokenId());
      ids.forEach((id) => {
        expect(id).toMatch(/^token_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
      });
    });
  });
});

