/**
 * Mock Password Hasher for Testing
 * Returns a fake bcrypt-like hash for testing
 */
export class MockPasswordHasher implements IPasswordHasher {
  async hash(plaintext: string): Promise<string> {
    // In real implementation, use bcrypt:
    // const bcrypt = require('bcrypt');
    // return bcrypt.hash(plaintext, 10);

    // For testing, create a deterministic bcrypt-like hash (60 chars)
    // Format: $2b$10$ + 22 salt chars + 31 hash chars
    // Hash the plaintext to get consistent but unique results
    const mockHash = this.createMockHash(plaintext);
    const mockSalt = "N9qo8uLOickgx2ZMRZoMye";
    return `$2b$10$${mockSalt}${mockHash}`;
  }

  private createMockHash(plaintext: string): string {
    // Create a deterministic 31-character hash from plaintext
    let hash = 0;
    for (let i = 0; i < plaintext.length; i++) {
      const char = plaintext.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32bit integer
    }

    // Convert to hex string and pad to 31 chars
    let hexHash = Math.abs(hash).toString(16).padStart(31, "0");
    return hexHash.substring(0, 31);
  }
}

/**
 * Mock Password Verifier for Testing
 */
export class MockPasswordVerifier implements IPasswordVerifier {
  async verify(plaintext: string, hash: string): Promise<boolean> {
    // In real implementation, use bcrypt:
    // const bcrypt = require('bcrypt');
    // return bcrypt.compare(plaintext, hash);

    // For testing, regenerate the hash and compare
    // This simulates bcrypt verification
    const hasher = new MockPasswordHasher();
    const expectedHash = await hasher.hash(plaintext);
    return hash === expectedHash;
  }
}

