import type { TUserId } from "@/types";
import type { IUserStore, IUser, IUserDBDTO } from "../user.interface";
import { db } from "../../database/client"; 
import { eq } from "drizzle-orm";
import { tryCatch } from "@/lib/try-catch-wrapper";
import { users } from "../../database/schema/user.repository";

class UserStore implements IUserStore {
  private static instance: UserStore;

  private constructor() {}

  public static getInstance(): UserStore {
    if (!UserStore.instance) {
      UserStore.instance = new UserStore();
    } 
    return UserStore.instance;
  };

  async createUser(data: IUserDBDTO & { password?: string }): Promise<IUserDBDTO> {
    return tryCatch({  
    ctx: async () => {
      const { password, ...userDataWithoutPassword } = data;
      const [createdUser] = await db.insert(users).values({
        id: userDataWithoutPassword.id,
        email: userDataWithoutPassword.email,
        name: userDataWithoutPassword.name,
        emailVerified: userDataWithoutPassword.emailVerified,
        image: userDataWithoutPassword.imageUrl,
      }).returning();
      if (!createdUser) {
        throw new Error("Failed to create user");
      }

      return {
        ...createdUser,
        imageUrl: createdUser.image,
      } as IUserDBDTO;
      }
    });
  };

  async getUserByEmail(email: string): Promise<IUserDBDTO | null> {
    return tryCatch({
      ctx: async () => {
        const [user] = await db.select().from(users).where(eq(users.email, email));
        if (!user) return null;
        return {
          ...user,
          imageUrl: user.image,
        } as IUserDBDTO;
      }
    });
  };

  async getUserById(id: TUserId): Promise<IUserDBDTO | null> {
    return tryCatch({
      ctx: async () => {
        const [user] = await db.select().from(users).where(eq(users.id, id));
        if (!user) return null;
        return {
          ...user,
          imageUrl: user.image,
        } as IUserDBDTO;
      }
    });
  };

  async deleteUser(id: TUserId): Promise<void> {
    return tryCatch({
      ctx: async () => {
        await db.delete(users).where(eq(users.id, id));
      }
    });
  };

  async updateUser(data: IUserDBDTO): Promise<IUserDBDTO> {
    return tryCatch({
      ctx: async () => {
        const [updatedUser] = await db.update(users).set({
          email: data.email,
          name: data.name,
          emailVerified: data.emailVerified,
          image: data.imageUrl,
          updatedAt: data.updatedAt,
        }).where(eq(users.id, data.id)).returning();
        if (!updatedUser) {
          return data;
        }
        return {
          ...updatedUser,
          imageUrl: updatedUser.image,
        } as IUserDBDTO;
      }
    });
  };
};

export const UserRepository = UserStore.getInstance();

