import { tryCatch } from "@/lib/try-catch-wrapper";
import { users } from "../../database/schema/user.repository";

class UserStore implements IUserStore {
  private static instance: UserStore;

  private constructor() {}

  public static getInstance(): UserStore {
    if (!UserStore.instance) {
      UserStore.instance = new UserStore();
    } 
    return UserStore.instance;
  };

  async createUser(data: IUser): Promise<IUserDBDTO> {
    return tryCatch({  
    ctx: async () => {
      const [createdUser] = await db.insert(users).values(data).returning();
      if (!createdUser) {
        throw new Error("Failed to create user");
      }

      return createdUser;
      }
    });
  };

  async getUserByEmail(email: string): Promise<IUserDBDTO | null> {
    return tryCatch({
      ctx: async () => {
        const [user] = await db.select().from(users).where(eq(users.email, email));
        return user || null;
      }
    });
  };

  async getUserById(id: TUserId): Promise<IUserDBDTO | null> {
    return tryCatch({
      ctx: async () => {
        const [user] = await db.select().from(users).where(eq(users.id, id));
        return user || null;
      }
    });
  };

  async deleteUser(id: TUserId): Promise<void> {
    return tryCatch({
      ctx: async () => {
        await db.delete(users).where(eq(users.id, id));
      }
    });
  };

  async updateUser(data: IUserDBDTO): Promise<IUserDBDTO> {
    return tryCatch({
      ctx: async () => {
        const [updatedUser] = await db.update(users).set(data).where(eq(users.id, data.id)).returning();
        return updatedUser || data;
      }
    });
  };
};

export const UserRepository = UserStore.getInstance();

